from control import *
alpha=np.array([1,-1,-1,1,1,-1,0])*np.pi/2
def fk0(q):
 T=np.eye(4)
 for a,d,qq in zip(alpha,[.36,0,.42,0,.4,0,.126],q[:7]):
  t=np.eye(4);t[:3,:3]=R.from_euler('z',qq).as_matrix()@R.from_euler('x',a).as_matrix();t[2,3]=d;T=T@t
 return T
if __name__=='__main__':
 cal=np.load(out+'/calib.npz');q0=cal['qbase'];src=np.load(out+'/hand_src.npy');inv0=np.linalg.inv(fk0(q0));data=[]
 for j in range(7):
  o=loadobs('cal'+str(j));p,_=cloud(o);tree=cKDTree(p);data.append((fk0(cal['qs'][j])@inv0,tree))
 def fun(b):
  B=np.eye(4);B[:3,3]=b[:3];B[:3,:3]=R.from_euler('z',b[3]).as_matrix();Bi=np.linalg.inv(B);err=[]
  for t,tree in data:
   a=apply(src,B@t@Bi);ds,ix=tree.query(a);err.extend(np.minimum(ds,.025))
  return err
 sol=least_squares(fun,[.034,.65,0,0],diff_step=1e-3,max_nfev=100);print(sol.x, np.mean(np.square(sol.fun))**.5)
 np.save(out+'/basefit.npy',sol.x)
 for j,(t,tree) in enumerate(data):
  B=np.eye(4);B[:3,3]=sol.x[:3];B[:3,:3]=R.from_euler('z',sol.x[3]).as_matrix();T=B@t@np.linalg.inv(B);print(j,'delta',T[:3,3],R.from_matrix(T[:3,:3]).as_rotvec())
PY
