from kin import *
o=capture('scoopstart');q=np.array(o.meta['proprio']['now'][58:87]);q0=np.load(out+'/qbase.npy');palm=np.array([.034,.09,.745]);rot=R.from_euler('x',.75).as_matrix()@R.from_euler('z',np.pi).as_matrix()@R.from_euler('x',np.pi).as_matrix()
def target(p):
 D=np.eye(4);D[:3,:3]=rot;D[:3,3]=np.array(p)-rot@palm;return D@fk(q0)
F=target([.49,.66,.15]);best=[]
for k in range(20):
 s=q.copy()
 if k:s[:7]=np.random.default_rng(k).uniform(np.array(spec['action_types']['joint_position']['lower'][:7])*.8,np.array(spec['action_types']['joint_position']['upper'][:7])*.8)
 t=ik(F,s)
 if np.linalg.norm(fk(t)-F)<.005:best.append((np.linalg.norm(t[:7]-q[:7]),t))
if best:
 t=min(best,key=lambda x:x[0])[1];t[7:]=0;move(t,5,'scoopbehind');F=target([.49,.605,.11]);t=ik(F,t);move(t,4,'scoopinsert')
 for i in [12,16,20,25]:t[i]=.3
 for i in [14,18,22,27]:t[i]=.6
 for i in [15,19,23,28]:t[i]=.4
 t[7]=1.2;t[9]=.8;t[11]=.8;move(t,3,'scoopcurl');F[2,3]+=.35;t=ik(F,t);move(t,5,'scooplift');move(t,1,'scoophold')
else:print('NO IK')
PY
